/* NU-021G: independent simulated silicon peripheral model, PB0 is
 * the ONLY host-driven input. Clocked compare and capture events are
 * generated by the simulated Timer1 and pin-capture peripherals.
 */
#include "sim_avr.h"
#include "avr_ioport.h"
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define MAX_STEPS 600
static int desired_level(unsigned long long age) {
    return (age>=5 && age<13) || (age>=22 && age<32) ||
           (age>=78 && age<91) || (age>=150 && age<162);
}
static int run(const char*filename,unsigned mask) {
    if(setvbuf(stdout,NULL,_IOLBF,0))return 2;
    uint8_t image[32768]={0};
    FILE*f=fopen(filename,"rb");if(!f)return 2;
    size_t n=fread(image,1,sizeof(image),f);fclose(f);
    if(n<0xc0 || n>=sizeof(image))return 2;
    avr_t*a=avr_make_mcu_by_name("atmega328p");
    if(!a||avr_init(a))return 3;
    a->frequency=16000000;
    avr_irq_t *pb0=avr_io_getirq(a,AVR_IOCTL_IOPORT_GETIRQ('B'),IOPORT_IRQ_PIN0);
    if(!pb0){avr_terminate(a);return 3;}
    avr_raise_irq(pb0,0);
    avr_loadcode(a,image,(uint32_t)n,0);
    unsigned sp_init=(unsigned)a->data[0x5d]+256U*a->data[0x5e];
    unsigned last_sp=sp_init,last_pc=0xffff,vec_cap=0,vec_a=0,vec_b=0;
    unsigned reti=0,step=0,edges=0,done=0,ready=0;
    unsigned long long ready_cycle=0;
    int level=0;
    for (unsigned i=1;i<=MAX_STEPS;i++){
        int rc=avr_run(a);
        if(rc!=cpu_Running && rc!=cpu_Sleeping){
            fprintf(stderr,"NU021G_STOP mask=%02x step=%u rc=%d\n",mask,i,rc);
            avr_terminate(a);return 4;
        }
        unsigned pc=(unsigned)a->pc/2U;
        unsigned sp=(unsigned)a->data[0x5d]+256U*a->data[0x5e];
        unsigned saved=(unsigned)a->data[sp_init]+256U*(unsigned)a->data[sp_init-1];
        if(pc==0x14&&last_pc!=0x14)vec_cap++;
        if(pc==0x16&&last_pc!=0x16)vec_a++;
        if(pc==0x18&&last_pc!=0x18)vec_b++;
        if(last_sp<sp_init && sp==sp_init)reti++;
        last_sp=sp;last_pc=pc;step=i;
        if(!ready && a->data[0x100]==0xa5){ready=1;ready_cycle=a->cycle;}
        unsigned long long age=ready?
             (unsigned long long)a->cycle-ready_cycle:0;
        int desired=ready?desired_level(age):0;
        if(desired!=level){
            avr_raise_irq(pb0,(uint32_t)desired);
            level=desired;
            if(level)edges++;
            printf("NU021G_PIN mask=%02x step=%u cycle=%llu level=%d age=%llu\n",
                mask,step,(unsigned long long)a->cycle,level,age);
        }
        printf("NU021G_TRACE mask=%02x step=%u pc_word=%04x cycle=%llu "
               "r20=%02x r21=%02x r22=%02x r23=%02x tifr1=%02x timsk1=%02x "
               "I=%u sp_delta=%d saved_pc=%04x pin=%d\n",
               mask,step,pc,(unsigned long long)a->cycle,
               (unsigned)a->data[20],(unsigned)a->data[21],
               (unsigned)a->data[22],(unsigned)a->data[23],
               (unsigned)a->data[0x36],(unsigned)a->data[0x6f],
               (unsigned)a->sreg[S_I],(int)sp_init-(int)sp,saved,level);
        if(a->data[20]>=4 && a->data[21]>=((mask&2)?2U:0U) &&
           a->data[22]>=((mask&4)?2U:0U) && sp==sp_init &&
           a->sreg[S_I]){done=1;break;}
    }
    unsigned want=4+((mask&2)?2:0)+((mask&4)?2:0);
    int ok=done&&ready&&edges==4 && a->data[20]==4 &&
         a->data[21]==((mask&2)?2U:0U) &&
         a->data[22]==((mask&4)?2U:0U) &&
         a->data[23]==0 && vec_cap>=4 &&
         vec_a>=((mask&2)?2U:0U) &&
         vec_b>=((mask&4)?2U:0U) && reti>=want;
    printf("NU021G_SUMMARY mask=%02x steps=%u pin_rising=%u "
        "capture=%u compa=%u compb=%u reti=%u pass=%d\n",mask,step,edges,
        (unsigned)a->data[20],(unsigned)a->data[21],
        (unsigned)a->data[22],reti,ok);
    avr_terminate(a);
    return ok?0:1;
}
int main(int argc,char**argv){
    if(argc!=3)return 2;
    unsigned mask=(unsigned)strtoul(argv[2],NULL,0);
    if(mask!=0x20 && mask!=0x22 && mask!=0x26)return 2;
    return run(argv[1],mask);
}
